#include <stdio.h>
#include <stdlib.h>

static inline int read_int() {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();
    if (c == EOF) return 0;
    int res = 0;
    while (c >= '0' && c <= '9') {
        res = res * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return res;
}

static inline char read_op() {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();
    return (char)c;
}

static char out_buf[1 << 20];
static int out_pos = 0;

static inline void write_char(char c) {
    if (out_pos == (1 << 20)) {
        fwrite(out_buf, 1, out_pos, stdout);
        out_pos = 0;
    }
    out_buf[out_pos++] = c;
}

static inline void write_long(long long x) {
    char s[24];
    int idx = 0;
    if (x == 0) {
        write_char('0');
        return;
    }
    while (x > 0) {
        s[idx++] = (char)('0' + (x % 10));
        x /= 10;
    }
    while (idx > 0) {
        write_char(s[--idx]);
    }
}

int main() {
    int n = read_int();
    int m = read_int();
    int p = read_int();

    int *row = (int *)malloc((n + 1) * sizeof(int));
    int *col = (int *)malloc((m + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) {
        row[i] = i;
    }
    for (int j = 1; j <= m; j++) {
        col[j] = j;
    }

    for (int k = 0; k < p; k++) {
        char op = read_op();
        int a = read_int();
        int b = read_int();

        if (op == 'L') {
            int tmp = row[a];
            row[a] = row[b];
            row[b] = tmp;
        } else if (op == 'C') {
            int tmp = col[a];
            col[a] = col[b];
            col[b] = tmp;
        }
    }

    long long M = m;
    for (int i = 1; i <= n; i++) {
        long long row_base = (long long)(row[i] - 1) * M;
        for (int j = 1; j <= m; j++) {
            long long val = row_base + col[j];
            write_long(val);
            if (j < m) {
                write_char(' ');
            } else {
                write_char('\n');
            }
        }
    }

    if (out_pos > 0) {
        fwrite(out_buf, 1, out_pos, stdout);
    }

    free(row);
    free(col);

    return 0;
}
